@triton.jit
def _logical_offset(linear, shapes: tl.constexpr, strides: tl.constexpr):
    offset = linear * 0
    for axis in tl.static_range(len(shapes) - 1, -1, -1):
        coordinate = linear % shapes.value[axis]
        linear = linear // shapes.value[axis]
        offset += coordinate * strides.value[axis]
    return offset


@libentry()
@triton.jit
def aminmax_backward_kernel(
    grad_min,
    grad_max,
    inp,
    min_output,
    max_output,
    grad_input,
    M,
    N: tl.constexpr,
    BATCH_SHAPES: tl.constexpr,
    BATCH_INPUT_STRIDES: tl.constexpr,
    BATCH_MIN_RESULT_STRIDES: tl.constexpr,
    BATCH_MAX_RESULT_STRIDES: tl.constexpr,
    BATCH_MIN_GRAD_STRIDES: tl.constexpr,
    BATCH_MAX_GRAD_STRIDES: tl.constexpr,
    BATCH_OUTPUT_STRIDES: tl.constexpr,
    REDUCE_SHAPES: tl.constexpr,
    REDUCE_INPUT_STRIDES: tl.constexpr,
    REDUCE_OUTPUT_STRIDES: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    row = tl.program_id(0)
    row_mask = row < M
    input_base = _logical_offset(row, BATCH_SHAPES, BATCH_INPUT_STRIDES)
    min_result_offset = _logical_offset(row, BATCH_SHAPES, BATCH_MIN_RESULT_STRIDES)
    max_result_offset = _logical_offset(row, BATCH_SHAPES, BATCH_MAX_RESULT_STRIDES)
    min_grad_offset = _logical_offset(row, BATCH_SHAPES, BATCH_MIN_GRAD_STRIDES)
    max_grad_offset = _logical_offset(row, BATCH_SHAPES, BATCH_MAX_GRAD_STRIDES)
    output_base = _logical_offset(row, BATCH_SHAPES, BATCH_OUTPUT_STRIDES)
    minimum = tl.load(min_output + min_result_offset, mask=row_mask)
    maximum = tl.load(max_output + max_result_offset, mask=row_mask)

    min_count = 0
    max_count = 0
    nan_count = 0
    for start in range(0, N, BLOCK_N):
        reduced = start + tl.arange(0, BLOCK_N)
        mask = row_mask & (reduced < N)
        input_offset = input_base + _logical_offset(
            reduced, REDUCE_SHAPES, REDUCE_INPUT_STRIDES
        )
        value = tl.load(inp + input_offset, mask=mask)
        min_count += tl.sum((value == minimum).to(tl.int32), axis=0)
        max_count += tl.sum((value == maximum).to(tl.int32), axis=0)
        nan_count += tl.sum((value != value).to(tl.int32), axis=0)

    min_count = tl.where(nan_count > 0, 0, min_count)
    max_count = tl.where(nan_count > 0, 0, max_count)
    min_grad = tl.load(grad_min + min_grad_offset, mask=row_mask).to(tl.float32)
    max_grad = tl.load(grad_max + max_grad_offset, mask=row_mask).to(tl.float32)
    scaled_min_grad = min_grad / min_count
    scaled_max_grad = max_grad / max_count
    for start in range(0, N, BLOCK_N):
        reduced = start + tl.arange(0, BLOCK_N)
        mask = row_mask & (reduced < N)
        input_offset = input_base + _logical_offset(
            reduced, REDUCE_SHAPES, REDUCE_INPUT_STRIDES
        )
        output_offset = output_base + _logical_offset(
            reduced, REDUCE_SHAPES, REDUCE_OUTPUT_STRIDES
        )
        value = tl.load(inp + input_offset, mask=mask)
        min_result = tl.where(value == minimum, scaled_min_grad, 0.0)
        max_result = tl.where(value == maximum, scaled_max_grad, 0.0)
        # Both native reductions propagate NaN gradients to their whole group.
        min_result = tl.where(min_count == 0, float("nan"), min_result)
        max_result = tl.where(max_count == 0, float("nan"), max_result)
        tl.store(grad_input + output_offset, min_result + max_result, mask=mask)


def _contiguous_strides(shape):
    strides = [0] * len(shape)
    stride = 1
    for axis in range(len(shape) - 1, -1, -1):
        strides[axis] = stride
        stride *= shape[axis]
    return tuple(strides)


def aminmax_backward(
    grad_min,
    grad_max,
    inp,
    min_output,
    max_output,
    dim=None,
    keepdim=False,
):
    """Fuse the tie-aware amin and amax input gradients into one launch."""
    logger.debug("GEMS AMINMAX_BACKWARD")
    if dim is None:
        reduce_dims = tuple(range(inp.ndim))
    elif isinstance(dim, int):
        reduce_dims = (dim % inp.ndim,)
    else:
        reduce_dims = tuple(axis % inp.ndim for axis in dim)

    batch_dims = tuple(axis for axis in range(inp.ndim) if axis not in reduce_dims)
    batch_shapes = tuple(inp.shape[axis] for axis in batch_dims)
    reduce_shapes = tuple(inp.shape[axis] for axis in reduce_dims)
    contiguous_strides = _contiguous_strides(inp.shape)
    batch_input_strides = tuple(inp.stride(axis) for axis in batch_dims)
    reduce_input_strides = tuple(inp.stride(axis) for axis in reduce_dims)
    batch_output_strides = tuple(contiguous_strides[axis] for axis in batch_dims)
    reduce_output_strides = tuple(contiguous_strides[axis] for axis in reduce_dims)
    if keepdim:
        batch_min_result_strides = tuple(min_output.stride(axis) for axis in batch_dims)
        batch_max_result_strides = tuple(max_output.stride(axis) for axis in batch_dims)
        batch_min_grad_strides = tuple(grad_min.stride(axis) for axis in batch_dims)
        batch_max_grad_strides = tuple(grad_max.stride(axis) for axis in batch_dims)
    else:
        reduced_rank = range(len(batch_dims))
        batch_min_result_strides = tuple(
            min_output.stride(axis) for axis in reduced_rank
        )
        batch_max_result_strides = tuple(
            max_output.stride(axis) for axis in range(len(batch_dims))
        )
        batch_min_grad_strides = tuple(
            grad_min.stride(axis) for axis in range(len(batch_dims))
        )
        batch_max_grad_strides = tuple(
            grad_max.stride(axis) for axis in range(len(batch_dims))
        )

    M = math.prod(batch_shapes)
    N = math.prod(reduce_shapes)
    grad_input = torch.empty(inp.shape, dtype=inp.dtype, device=inp.device)
    # A 512-element tile bounds register pressure while retaining enough work
    # per program for the fused tie-count and gradient-write passes.
    block_n = min(512, triton.next_power_of_2(N))
    with torch_device_fn.device(inp.device):
        aminmax_backward_kernel[(M,)](
            grad_min,
            grad_max,
            inp,
            min_output,
            max_output,
            grad_input,
            M,
            N=N,
            BATCH_SHAPES=batch_shapes,
            BATCH_INPUT_STRIDES=batch_input_strides,
            BATCH_MIN_RESULT_STRIDES=batch_min_result_strides,
            BATCH_MAX_RESULT_STRIDES=batch_max_result_strides,
            BATCH_MIN_GRAD_STRIDES=batch_min_grad_strides,
            BATCH_MAX_GRAD_STRIDES=batch_max_grad_strides,
            BATCH_OUTPUT_STRIDES=batch_output_strides,
            REDUCE_SHAPES=reduce_shapes,
            REDUCE_INPUT_STRIDES=reduce_input_strides,
            REDUCE_OUTPUT_STRIDES=reduce_output_strides,
            BLOCK_N=block_n,
            num_warps=4,
        )
    return grad_input


class AminmaxFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, inp, dim, keepdim):
        min_output, max_output = _aminmax_impl(inp, dim=dim, keepdim=keepdim)
        ctx.save_for_backward(inp, min_output, max_output)
        ctx.dim = dim
        ctx.keepdim = keepdim
        return min_output, max_output

    @staticmethod
    def backward(ctx, grad_min, grad_max):
        inp, min_output, max_output = ctx.saved_tensors
        return (
            aminmax_backward(
                grad_min,
                grad_max,
                inp,
                min_output,
                max_output,
                ctx.dim,
                ctx.keepdim,
            ),
            None,
            None,
        )


@libentry()
@triton.jit
def aminmax_kernel_1(
    inp,
    min_out,
    max_out,
    M,
    BLOCK_SIZE: tl.constexpr,
):
    pid = ext.program_id(0)

    offset = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    inp_ptrs = inp + offset
    mask = offset < M
    min_fill = get_dtype_max(inp.type.element_ty)
    max_fill = get_dtype_min(inp.type.element_ty)
    min_val = tl.load(inp_ptrs, mask=mask, other=min_fill)
    max_val = tl.load(inp_ptrs, mask=mask, other=max_fill)

    min_val = tl.min(min_val)
    max_val = tl.max(max_val)

    min_ptr = min_out + pid
    max_ptr = max_out + pid
    tl.store(min_ptr, min_val)
    tl.store(max_ptr, max_val)


@libentry()
@triton.jit
def aminmax_kernel_2(
    min_inp, max_inp, min_out, max_out, mid_size, BLOCK_MID: tl.constexpr
):
    offset = tl.arange(0, BLOCK_MID)
    min_ptrs = min_inp + offset
    max_ptrs = max_inp + offset
    mask = offset < mid_size
    min_fill = get_dtype_max(min_inp.type.element_ty)
    max_fill = get_dtype_min(max_inp.type.element_ty)
    min_val = tl.load(min_ptrs, mask=mask, other=min_fill)
    max_val = tl.load(max_ptrs, mask=mask, other=max_fill)

    min_val = tl.min(min_val)
    max_val = tl.max(max_val)

    tl.store(min_out, min_val)
    tl.store(max_out, max_val)


@libentry()
@libtuner(
    configs=runtime.get_tuned_config("naive_reduction"),
    key=["M", "N"],
)
@triton.jit
def aminmax_kernel(
    inp,
    min_out,
    max_out,
    M,
    N,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    dtype = inp.type.element_ty
    min_value = get_dtype_min(dtype)
    max_value = get_dtype_max(dtype)

    # Map the program id to the row of inp it should compute.
    pid = ext.program_id(0)
    rows = pid * BLOCK_M + tl.arange(0, BLOCK_M)[:, None]
    inp = inp + rows * N
    min_out = min_out + rows
    max_out = max_out + rows
    row_mask = rows < M

    acc_type = tl.float32 if dtype is tl.bfloat16 else dtype
    _min = tl.full([BLOCK_M, BLOCK_N], value=max_value, dtype=acc_type)
    _max = tl.full([BLOCK_M, BLOCK_N], value=min_value, dtype=acc_type)
    for off in range(0, N, BLOCK_N):
        cols = off + tl.arange(0, BLOCK_N)[None, :]
        col_mask = cols < N
        mask = row_mask & col_mask
        a = tl.load(inp + cols, mask=mask, other=min_value)
        _min = tl.where(mask, tl.minimum(_min, a), _min)
        _max = tl.where(mask, tl.maximum(_max, a), _max)
    min_result = tl.min(_min, axis=1)[:, None]
    max_result = tl.max(_max, axis=1)[:, None]
    tl.store(min_out, min_result, row_mask)
    tl.store(max_out, max_result, row_mask)


def _aminmax_impl(inp, dim=None, keepdim=False, *, out=None):
    if dim is None:
        # The whole-tensor kernels use flat offsets, so materialize strided views.
        inp = contiguous(inp)
        M = inp.numel()
        block_size = triton.next_power_of_2(math.ceil(math.sqrt(M)))
        mid_size = triton.cdiv(M, block_size)
        block_mid = triton.next_power_of_2(mid_size)
        dtype = inp.dtype
        min_mid = torch.empty((mid_size,), dtype=dtype, device=inp.device)
        max_mid = torch.empty((mid_size,), dtype=dtype, device=inp.device)

        if out is not None:
            min_out = out[0] if isinstance(out, tuple) else out
            max_out = out[1] if isinstance(out, tuple) else out
            if not keepdim:
                min_out = min_out.squeeze()
                max_out = max_out.squeeze()
        else:
            if not keepdim:
                min_out = torch.empty([], dtype=dtype, device=inp.device)
                max_out = torch.empty([], dtype=dtype, device=inp.device)
            else:
                shape = [1] * inp.dim()
                min_out = torch.empty(shape, dtype=dtype, device=inp.device)
                max_out = torch.empty(shape, dtype=dtype, device=inp.device)

        with torch_device_fn.device(inp.device):
            aminmax_kernel_1[(mid_size, 1)](
                inp,
                min_mid,
                max_mid,
                M,
                block_size,
            )
            aminmax_kernel_2[(1, 1)](
                min_mid, max_mid, min_out, max_out, mid_size, block_mid
            )
        return min_out, max_out
    else:
        if isinstance(dim, int):
            dim = [dim]
        assert ((i >= -inp.ndim and i < inp.ndim) for i in dim), "Invalid dim"
        dtype = inp.dtype

        shape = list(inp.shape)
        dim = [d % inp.ndim for d in dim]
        inp = dim_compress(inp, dim)
        N = 1
        for i in dim:
            N *= shape[i]
            shape[i] = 1
        M = inp.numel() // N

        if out is not None:
            min_out = out[0] if isinstance(out, tuple) else out
            max_out = out[1] if isinstance(out, tuple) else out
        else:
            min_out = torch.empty(shape, dtype=dtype, device=inp.device)
            max_out = torch.empty(shape, dtype=dtype, device=inp.device)

        grid = lambda meta: (triton.cdiv(M, meta["BLOCK_M"]),)
        with torch_device_fn.device(inp.device):
            aminmax_kernel[grid](inp, min_out, max_out, M, N)
        if not keepdim:
            min_out = min_out.squeeze(dim=dim)
            max_out = max_out.squeeze(dim=dim)
        return min_out, max_out


def aminmax(inp, dim=None, keepdim=False, *, out=None):
    logger.debug("GEMS AMINMAX")
    if out is None and torch.is_grad_enabled() and inp.requires_grad:
        return AminmaxFunction.apply(inp, dim, keepdim)
    return _aminmax_impl(inp, dim=dim, keepdim=keepdim, out=out)
